# 数据文件：src/components/permissions/AskUserQuestionPermissionRequest/AskUserQuestionPermissionRequest.tsx
# slug = src_components_permissions_AskUserQuestionPermissionRequest_AskUserQuestionPermissionRequest_tsx
# 规则：一个源文件 = 一个数据文件；中文用三引号；禁止英文双引号 " 与反斜杠 \（用「」/『』代替）。
ANNOTATIONS = [
    (1, 'before', '''本文件是「向用户提问」工具的权限请求界面：把模型发起的多问题访谈渲染成可导航的问答表单。三层结构——外层组件做语法高亮的懒加载分流（Suspense 加 use 挂起），Body 主体管理问题状态机与四种终点动作（提交回答、取消、向 Claude 回话、结束计划访谈），尾部是编译器提升的若干谓词小函数。React Compiler 产物特征：几乎每个分支都包进 memo 缓存 if 块（用 $ 数组下标判等），读时抓语句主干即可。'''),
    (26, 'before', '''三个尺寸常量定内容区下限：高度 12 行、宽度 40 列是任何终端都保得住的最小问答面板；CHROME_OVERHEAD 15 行预留给导航条、标题、页脚、帮助文案等外围 chrome，用终端总行数减掉它才是内容区可用高度。'''),
    (30, 'before', '''入口组件只做一件事：按是否启用语法高亮走两条渲染路径。关高亮直接渲染 Body 且 highlight 传 null；开高亮包 Suspense 挂起等待高亮模块就绪。两条路径各带 memo 缓存守卫，props 不变就复用上次结果。'''),
    (33, 'before', '''关闭语法高亮（settings 显式声明）时跳过懒加载：直接渲染 Body，highlight 为 null，applyMarkdown 会按纯文本处理。'''),
    (44, 'before', '''开启高亮的路径：用 Suspense 包住带高亮的子组件，fallback 是无高亮版本——高亮模块加载完成前用户就能看到可交互的表单，不白等。'''),
    (54, 'before', '''挂起点：React 19 的 use 钩子直接吃 Promise。getCliHighlightPromise 只在首次渲染时创建（sentinel 分支缓存），后续渲染复用同一 Promise；未就绪时组件在此挂起，由上层 Suspense 接管显示 fallback。'''),
    (75, 'before', '''Body 主体，真正的状态机容器。_c(115) 分配 115 个 memo 缓存槽，是本文件最大的组件——输入解析、尺寸测量、图片粘贴、四种动作回调都在这里。编译器把每段派生计算包成「依赖判等再重算或取缓存」的样板，跳过 $ 判断直接看赋值语句即可。'''),
    (84, 'before', '''输入解析：用工具自带的 zod schema 安全解析 toolUseConfirm 的 input；解析失败时 questions 退化为空数组——模型给的输入格式漂移也不会崩。'''),
    (106, 'before', '''尺寸测量：maxHeight 与 maxWidth 从 0 起跨所有问题取最大值，保证切换问题时面板不跳动；maxAllowedHeight 是终端行数减 chrome 开销的下限保护。'''),
    (110, 'before', '''逐问题测量：带预览的选项要渲染 markdown 预览框，走左右分栏高度公式（左列选项数加 2、右列预览框加 2 取大者再加 7 行 chrome）；无预览走简单公式（选项数加 3 加 7）。宽度取所有预览行 stringWidth 的最大值。'''),
    (145, 'before', '''最终 clamp：高度夹在最小值与 maxAllowedHeight 之间，宽度至少 40 列。测出的值作为全局内容区尺寸传给 QuestionView，让所有问题的布局基准一致。'''),
    (163, 'before', '''metadataSource 是遥测来源标记（计划访谈、权限流程等）；只有带来源的问题集才上报分析事件，手动触发的提问不打点。'''),
    (171, 'before', '''图片粘贴：pastedContentsByQuestion 以问题文本为键，存每个问题下粘贴的图片（id 到内容的映射）；nextPasteIdRef 用 ref 自增生成粘贴 id，避免 setState 竞态。'''),
    (175, 'before', '''onImagePaste：构造 PastedContent（默认 png、默认文件名），先 cacheImagePath 加 storeImage 落盘，再按问题键合并进 state。整个函数被编译器缓存为单例（sentinel 分支），不随渲染重建。'''),
    (203, 'before', '''onRemoveImage：按问题键删指定 id 的图片，其余键保持不动。'''),
    (229, 'before', '''计划模式联动：useAppState 的 selector 读当前权限上下文模式；处于 plan 模式时这组问题被视为计划访谈的一环，会带上计划文件路径并启用专属的结束动作。'''),
    (240, 'before', '''多选状态机来自 useMultipleChoiceState：当前问题下标、答案表、每问题的文本输入状态、是否在文本输入模式，以及导航、更新、提交动作。currentQuestionIndex 等于问题数时进入提交确认视图。'''),
    (267, 'before', '''终点一（取消）：三连动作——带来源时上报 rejected 事件（含是否计划访谈与访谈阶段开关）、onDone 关权限请求、toolUseConfirm 的 onReject 拒绝工具调用。注意 props 上的 onReject 与 toolUseConfirm.onReject 是两层。'''),
    (293, 'before', '''终点二（向 Claude 回话）：不直接提交，而是把「用户想澄清」拼成反馈文本回传模型——逐问题列出问答对（未答的标注未提供答案），模板开头指示模型先问用户想澄清什么。图片附件转成 image block 一起回传；走 onReject 带反馈文本——拒绝工具调用但把上下文塞回去。'''),
    (333, 'before', '''终点三（结束计划访谈）：仅计划访谈场景——反馈文本换成「用户已答够，停止追问，用现有信息完成计划」，同样走 onReject 携带问答对回传。'''),
    (371, 'before', '''终点四（提交回答）：核心提交路径——答案表塞进 updatedInput 的 answers；带预览或文本备注的问答进 annotations；图片转 contentBlocks；最后 onAllow 提交更新后的输入。'''),
    (381, 'before', '''annotations 只收集有增量信息的问题：选了带预览的选项、或在文本框写了备注——两者都空就不进表，避免给模型发空对象。'''),
    (423, 'before', '''QuestionView 的 onAnswer 汇聚点：多选时把标签数组 join 成逗号串；文本输入时若有粘贴图片就在答案尾部追加「已附图」标注；哨兵值 __other__ 且只贴了图时答案整个替换为「已附图」。'''),
    (465, 'before', '''提交视图的最终分派：cancel 走 handleCancel，submit 用当前答案表调 submitAnswers——提交视图不再改答案，只做确认。'''),
    (482, 'before', '''maxIndex 决定页签导航上界：单问题且非多选时隐藏提交页签，上界是最后一个问题；否则允许走到提交页（下标等于问题数）。'''),
    (513, 'before', '''Tab 键位：tabs:previous 与 tabs:next 分派到状态机的 prev 与 next，各自带下标边界检查。'''),
    (524, 'before', '''文本输入聚焦且不在提交视图时禁用 Tab 导航——否则在文本框里按 Tab 或 Shift-Tab 会跳问题丢焦点。'''),
    (537, 'before', '''渲染分派一：当前问题存在则渲染 QuestionView，把尺寸预算、答案、状态、四个动作回调和图片粘贴三件套全部下传。onSubmit 传的是 nextQuestion——单问题非多选时 answer 回调里已直接提交，多问题的「下一个」由 Enter 触发。'''),
    (593, 'before', '''渲染分派二：全部问题答完进入提交视图，渲染 SubmitQuestionsView 做总览确认；permissionResult 透传用于显示权限信息。'''),
    (612, 'before', '''编译器提升的谓词群：六个全是单行判断——三份同构的图片类型过滤、权限模式读取、展平粘贴内容、判定选项有无预览。按语义对应回 Body 里的调用点读。'''),
    (630, 'before', '''图片转 block：把 PastedContent 数组逐个构造成 Anthropic API 的 image block（base64 源），每个都过一遍缩放与降采样再返回；空数组直接返回 undefined，让调用方省掉空参数分支。'''),
]
